def max_in_channel_manual(batch):
    """
    Finds the maximum value in every channel for each image in the batch without using NumPy's np.max function.

    Args:
    batch: A 3D NumPy array representing a batch of images. The shape of the array is (num_images, height, width, channels).

    Returns:
    A 2D NumPy array containing the maximum value in every channel for each image. The shape of the array is (num_images, channels).
    """
    num_images, height, width, channels = batch.shape
    max_values = []
    for image in batch:
        max_in_channels = []
        for channel in range(channels):
            max_val = float('-inf')
            for h in range(height):
                for w in range(width):
                    max_val = max(max_val, image[h, w, channel])
            max_in_channels.append(max_val)
        max_values.append(max_in_channels)
    return np.array(max_values)

