class Memcached:
    def __init__(self):
        self.cache = {}

    def set(self, key, value, ttl):
        self.cache[key] = (value, time.time() + ttl)

    def get(self, key):
        if key in self.cache:
            value, expiry = self.cache[key]
            if time.time() < expiry:
                return value
            else:
                del self.cache[key]
        return None

    def delete(self, key):
