class QuoridorEnv:
    def __init__(self):
        self.board = [[' ' for _ in range(9)] for _ in range(9)]
        self.player1_pos = (0, 4)
        self.player2_pos = (8, 4)
        self.board[self.player1_pos[0]][self.player1_pos[1]] = '1'
        self.board[self.player2_pos[0]][self.player2_pos[1]] = '2'

    def reset(self):
        self.board = [[' ' for _ in range(9)] for _ in range(9)]
        self.player1_pos = (0, 4)
        self.player2_pos = (8, 4)
        self.board[self.player1_pos[0]][self.player1_pos[1]] = '1'
        self.board[self.player2_pos[0]][self.player2_pos[1]] = '2'

    def step(self, action):
        player, direction = action
        if player == 1:
            new_pos = self.move_player(self.player1_pos, direction)
            if new_pos != self.player1_pos:
                self.board[self.player1_pos[0]][self.player1_pos[1]] = ' '
                self.player1_pos = new_pos
                self.board[self.player1_pos[0]][self.player1_pos[1]] = '1'
        else:
            new_pos = self.move_player(self.player2_pos, direction)
            if new_pos != self.player2_pos:
                self.board[self.player2_pos[0]][self.player2_pos[1]] = ' '
                self.player2_pos = new_pos
                self.board[self.player2_pos[0]][self.player2_pos[1]] = '2'

    def move_player(self, position, direction):
        row, col = position
        if direction == 'up' and row > 0 and self.board[row - 1][col] == ' ':
            return row - 1, col
        elif direction == 'down' and row < 8 and self.board[row + 1][col] == ' ':
            return row + 1, col
        elif direction == 'left' and col > 0 and self.board[row][col - 1] == ' ':
            return row, col - 1
        elif direction == 'right' and col < 8 and self.board[row][col + 1] == ' ':
            return row, col + 1
        return position

    def render(self):
        for row in self.board:
            print(' '.join(row))

