    dependency_map = {name: timestamp for name, timestamp in dependencies}
    dependency_set = set(dependencies)
    order = []

    while dependency_set:
        resolved = False
        for name, timestamp in list(dependency_set):
            if all(dep in order for dep in dependency_map.get(name, [])):
                order.append(name)
                dependency_set.remove((name, timestamp))
                resolved = True

        if not resolved:
            raise ValueError("Circular dependency detected")

    return order

