def count_lines_in_file(file_path: str, buf_size: int) -> int:
    def read_f(size):
        with open(file_path, 'rb') as file:
            while True:
                data = file.read(size)
                if not data:
                    break
                yield data

    num_lines = 0
    with open(file_path, 'rb') as file:
        buf = b''
        for chunk in read_f(buf_size):
            buf += chunk
            num_lines += buf.count(b'\n')
            buf = buf.rsplit(b'\n', 1)[-1]  # Keep the last incomplete line for the next iteration
    return num_lines

