from typing import List

def searchInsert(nums: List[int], target: int) -> int:
    # exception case
    if not isinstance(nums, list) or len(nums) == 0:
        return 0

    # main method: (loop) binary search of sorted list
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return left

