def second_largest(nums: List[int]) -> int:
    max_num = float('-inf')
    second_max_num = float('-inf')

    for num in nums:
        if num > max_num:
            second_max_num = max_num
            max_num = num
        elif num > second_max_num and num < max_num:
            second_max_num = num

