class ImageProcessor:
    def __init__(self, binary_image):
        self.binary_image = binary_image

    def erode(self, iterations):
        for _ in range(iterations):
            eroded_image = [[0 for _ in range(len(self.binary_image[0]))] for _ in range(len(self.binary_image))]
            for i in range(len(self.binary_image)):
                for j in range(len(self.binary_image[0])):
                    if self.binary_image[i][j] == 1:
                        if i > 0 and self.binary_image[i - 1][j] == 1 and \
                           i < len(self.binary_image) - 1 and self.binary_image[i + 1][j] == 1 and \
                           j > 0 and self.binary_image[i][j - 1] == 1 and \
                           j < len(self.binary_image[0]) - 1 and self.binary_image[i][j + 1] == 1:
                            eroded_image[i][j] = 1
            self.binary_image = eroded_image

    def dilate(self, iterations):
        for _ in range(iterations):
            dilated_image = [[0 for _ in range(len(self.binary_image[0]))] for _ in range(len(self.binary_image))]
            for i in range(len(self.binary_image)):
                for j in range(len(self.binary_image[0])):
                    if self.binary_image[i][j] == 1:
                        dilated_image[i][j] = 1
                        if i > 0:
                            dilated_image[i - 1][j] = 1
                        if i < len(self.binary_image) - 1:
                            dilated_image[i + 1][j] = 1
                        if j > 0:
                            dilated_image[i][j - 1] = 1
                        if j < len(self.binary_image[0]) - 1:
                            dilated_image[i][j + 1] = 1
            self.binary_image = dilated_image

