class ThreadSafeIterator:
    def __init__(self, dataset):
        self.dataset = dataset
        self.index = 0
        self.lock = threading.Lock()

    def __iter__(self):
        return self

    def __next__(self):
        with self.lock:
            if self.index < len(self.dataset):
