        if is_lonely:
            lonely_nodes.append(node.value)
        if (node.left is None) ^ (node.right is None):
            is_lonely = True
        else:
            is_lonely = False
        dfs(node.left, is_lonely)
        dfs(node.right, is_lonely)

    dfs(root, False)
    return lonely_nodes

