class ShortPulseGenerator(PulseShapeGenerator):
    def __init__(self, pulse_width):
        self.pulse_width = pulse_width

    def generate_pulse(self, symbol_duration):
        t = np.linspace(0, symbol_duration, symbol_duration * 10, endpoint=False)
